/**
 * ═══════════════════════════════════════════════════════════════════════════
 *                    ADVANCED RAG PIPELINE SERVICE
 * ═══════════════════════════════════════════════════════════════════════════
 *
 * Retrieval-Augmented Generation pipeline with:
 * - LLM-based reranking for improved relevance
 * - HyDE (Hypothetical Document Embeddings) for query expansion
 * - Multi-query retrieval for better coverage
 * - Maximal Marginal Relevance (MMR) for diversity
 * - Contextual compression for token efficiency
 *
 * TECHNIQUES IMPLEMENTED:
 * 1. HyDE - Generate hypothetical answer, embed that
 * 2. Multi-Query - Expand query into multiple perspectives
 * 2b. Step-Back - Derive a broader question (rag-query-transforms.ts) and
 *     retrieve on it alongside the original for background context
 * 2c. Decompose - Split a multi-part question into atomic sub-questions
 *     (rag-query-transforms.ts) and retrieve each alongside the original
 * 3. Reranking - pluggable via rag-reranker.ts. Defaults to an LLM-as-judge
 *    (a prompted relevance score, NOT a cross-encoder); swaps to a true
 *    cross-encoder reranker when RAG_RERANKER_* env is configured.
 * 4. MMR - Balance relevance with diversity, measured in embedding space
 * 5. Contextual Compression - Extract only relevant passages
 * 6. Small-to-Big - Rank on precise chunks, then expand each to its neighbour
 *    window in the source document so generation reads the surrounding context
 * 7. Corrective loop (CRAG/Self-RAG) - rag-corrective-loop.ts. Opt-in: grade
 *    context sufficiency + rewrite/re-retrieve, then a groundedness guard that
 *    flags answers unsupported by sources. Annotates rather than withholds.
 *
 * The auxiliary reasoning steps (HyDE, query expansion, reranking, compression)
 * are cached in-memory per identical request to cut redundant LLM round-trips;
 * the final grounded answer is never cached.
 *
 * @author Concept2Cure AI Team
 * @version 2.0.0
 * @license Proprietary - Concept2Cure Inc.
 */

import Anthropic from '@anthropic-ai/sdk';
import type OpenAI from 'openai';
import pg from 'pg';
import type { RequestSqlClient } from '../db/requestDb.js';
import { assertVerifiedProgramScope, requireProgramScopeStillCurrent, ProgramReadAccessError, type CurrentAccessibleProgramScope } from './c2c/current-program-access.js';
import {
  atomDataEligibleSql, atomOriginalFileAvailableSql, vaultDataEligibleSql,
  vaultBinaryAvailableSql, ragDataEligibleSql, ragOriginalFileAvailableSql,
} from './document-data-disposition/eligibility.js';
import { createHash, randomUUID } from 'node:crypto';
import { EnhancedEmbeddingService, getEmbeddingService } from './enhancedEmbeddingService.js';
import { assertTenantIsCurrent, isTenantUuid, type TenantKeyQueryable } from '../db/currentTenant.js';
import { getTenantScope } from '../db/tenantStore.js';
import { refuseModelCallHere } from './ai-gateway/model-call-scope.js';
import { getOrgPlacementResolver } from './ai-gateway/providers/org-placement.js';
import { AIProviderRouter, getAIRouter, type AIRequest, type AIResponse } from './aiProviderRouter.js';
import { getOpenAIClient } from './openai-client.js';
import { getReranker, type Reranker } from './rag-reranker.js';
import { buildRagGenerationRequest, buildRagSourceText, RAG_EMPTY_CONTEXT_REFUSAL } from './rag-generation-request.js';
import { fuseHybrid, mergeByMaxScore } from './rag-fusion.js';
import { anyTermsQuery } from './vault/vault-search.js';
import { supersededSql } from './vault/vault-version-family.js';
import { missingVectorIndex } from './vault/vector-index-availability.js';
import type { AdmittedAnaSourceReadScope } from './ana/source-read-scope.js';
import { revalidateAnaSourceReadScope } from './ana/source-read-scope.js';
import { pinRetrievalReadScope, withRetrievalReadScope } from './vault/retrieval-source-access.js';
import { buildPassageContext, type PassageContext } from './vault/passage-context-span.js';
import {
  hydeRetrieval,
  multiQueryRetrieval,
  stepBackRetrieval,
  decomposeRetrieval,
  type StrategyDeps,
} from './rag-retrieval-strategies.js';
import {
  gradeContextSufficiency,
  rewriteQuery,
  verifyGroundedness,
} from './rag-corrective-loop.js';
import { extractQueryFilters } from './rag-query-transforms.js';
import {
  buildDocFilterClause,
  mergeFilters,
  VAULT_FILTER_COLUMNS,
  RAG_FILTER_COLUMNS,
  type QueryFilters,
} from './rag-filters.js';

// ═══════════════════════════════════════════════════════════════════════════
//                          TYPE DEFINITIONS
// ═══════════════════════════════════════════════════════════════════════════

/** Server-only read composition. The scope must be minted on this exact executor. */
export interface VerifiedVaultRead {
  sqlClient: RequestSqlClient;
  organizationId: number;
  userId: number;
  programId: string | null;
  verifiedScope: CurrentAccessibleProgramScope;
}

export interface RetrievalOptions {
  /** Current Vault reader only; cannot authorize another corpus or a writer. */
  vaultRead?: VerifiedVaultRead;
  strategy: 'basic' | 'hyde' | 'multi_query' | 'step_back' | 'decompose' | 'advanced';
  /**
   * Pin the model that generates the answer in `queryWithGeneration`, by
   * gateway model id. Retrieval itself is unaffected — this names the
   * GENERATOR, which is the only part of a RAG run a model can be qualified
   * on. Absent (the normal case) the gateway selects for the task type as
   * before, so this changes nothing for existing callers.
   *
   * The gateway still refuses an unapproved model on a high-risk task — see
   * AIRequest.model. This is attribution, not an approval override.
   */
  model?: string;
  limit?: number;
  threshold?: number;
  useReranking?: boolean;
  /**
   * The rerank score will decide a governed verdict (a citation run's
   * supported / gap status). The reranker then serves it only from a model
   * approved for regulatory review, and a rerank that fails throws instead of
   * silently keeping the embedding order — the verdict threshold is set for the
   * blended score, so an embedding-only score would be judged on the wrong
   * scale. See RerankOptions.governedVerdict in rag-reranker.ts.
   */
  governedVerdict?: boolean;
  useMmr?: boolean;
  mmrLambda?: number; // 0 = max diversity, 1 = max relevance
  /**
   * Fuse dense (vector) retrieval with a sparse (Postgres full-text) retrieval
   * via Reciprocal Rank Fusion on the vault / rag_chunks corpora. Recovers
   * keyword/exact-term matches that pure embeddings miss (codes, acronyms, rare
   * tokens) without sacrificing semantic recall. Ignored by the project-atom and
   * memory paths (project atoms already run their own hybrid; memory stays
   * similarity-pure). Off unless set — the router enables it per intent.
   */
  useHybrid?: boolean;
  /**
   * Small-to-big context expansion. After ranking on precise small chunks,
   * expand each vault / rag_chunks result to include its neighbouring chunks in
   * the same document (a ±`contextWindow` sentence-window) so generation sees
   * the surrounding context the chunk alone omits. Off unless set. No effect on
   * project-atom / memory corpora (no chunk index to window over).
   */
  useContextExpansion?: boolean;
  /** Neighbours to include on each side for useContextExpansion (default 1). */
  contextWindow?: number;
  /**
   * Agentic corrective loop (CRAG / Self-RAG) around generation: grade whether
   * the retrieved sources can answer the question and, if not, rewrite the query
   * and retrieve once more; then verify the drafted answer is grounded in the
   * sources and flag it when it is not. Off unless set — opt-in on the generation
   * path, and it annotates (a `grounded` flag) rather than withholding answers.
   */
  useCorrectiveLoop?: boolean;
  /**
   * Self-querying: extract metadata constraints (document type, source, date
   * range) from the natural-language query via the LLM and apply them as SQL
   * pre-filters on the vault / rag_chunks corpora, merged under any explicit
   * `filters` (explicit wins). Off unless set. No effect on project-atom /
   * memory corpora, and `filters.domain` is never applied (no column exists).
   */
  useSelfQuery?: boolean;
  useCompression?: boolean;
  organizationUuid?: string;
  persistCitations?: boolean;
  filters?: QueryFilters;
  /** Canonical server-owned AnA actor scope; never a request-body filter. */
  sourceReadScope?: AdmittedAnaSourceReadScope;
  /**
   * Constrain initial retrieval to atoms belonging to artifacts under a
   * specific Concept2Cure project. When set, the pipeline routes through
   * `lumen_data_atoms` with the project-scoped hybrid search (the same
   * surface as `enhancedEmbeddingService.searchHybrid`) instead of the
   * vault. HyDE / multi-query / rerank / MMR all run on top of that
   * project-scoped candidate set, so cross-module retrieval stays inside
   * the dossier.
   *
   * Required by submission-chat: `artifactScope.organizationUuid` plus
   * `artifactScope.projectId` push the project filter into the SQL so
   * we never leak cross-project chunks into a project's interrogation.
   */
  artifactScope?: {
    projectId: number | string;
    organizationUuid: string;
  };
  /**
   * Which corpus to retrieve from. Defaults to the vault. Set 'rag_chunks' to
   * target the rag_chunks corpus (the registered hot-path chunk store also used
   * by the biotech surface), scoped by the integer `organizationId` below. This
   * is the single-router path that lets callers reach rag_chunks without a
   * separate retrieval engine. `artifactScope` takes precedence when set.
   */
  corpus?: 'vault' | 'rag_chunks' | 'client_memory' | 'project_memory';
  /**
   * Integer organization id for `corpus: 'rag_chunks'` tenant scoping
   * (rag_documents.organization_id). rag_chunks is not RLS-scoped, so this is
   * applied as an explicit WHERE filter — omitting it returns cross-tenant rows.
   * Also the tenant scope for the memory corpora (client/project_memory).
   */
  organizationId?: number;
  /**
   * Scoping for the memory corpora (`corpus: 'client_memory' | 'project_memory'`).
   * These run a pure pgvector similarity search over the memory tables, so they
   * should be invoked with `strategy: 'basic'` and reranking/MMR/compression off
   * to stay similarity-pure (the document reranker is not meaningful for memory
   * atoms).
   */
  memoryScope?: MemoryScope;
}

/** Filters for the memory corpora, mirroring the searchMemoryEntriesSemantic query. */
export interface MemoryScope {
  /** client_memory: optional profile filter. */
  profileId?: number | null;
  /** project_memory: required project filter. */
  projectId?: number;
  /** project_memory: optional project-profile filter. */
  projectProfileId?: number | null;
  /** Optional category filter (both memory corpora). */
  category?: string;
}

type VaultPassageSnapshot = {
  extractedTextSha256: string | null;
  charStart: number | null;
  charEnd: number | null;
};

export interface RetrievedDocument {
  id: string;
  documentId?: string;
  programId?: string;
  contentHash?: string;
  /** Internal same-statement extraction/chunk snapshot; not an exact-span reference. */
  vaultPassageSnapshot?: VaultPassageSnapshot;
  chunkId?: string;
  content: string;
  title: string;
  atomType: string;
  source?: string;
  initialScore: number; // From embedding similarity
  /** Found by the text index alone: the query could not be embedded (no key, or egress refused). */
  lexicalOnly?: boolean;
  rerankScore?: number; // From the LLM relevance judge (LLM-as-judge, not a cross-encoder)
  finalScore: number; // Combined score
  /** Freshly checked availability of the captured binary, distinct from retained data. */
  originalFileAvailable?: boolean;
  compressedContent?: string; // Extracted relevant passage
  /**
   * Small-to-big context expansion: the retrieved chunk with its neighbours in
   * the source document. Set by expandContext when useContextExpansion is on;
   * generation and compression prefer it over the bare chunk. For a vault
   * chunk it is the exact source span (`passageContext.text`), never joined
   * chunk text; when the span cannot be verified it is left unset.
   */
  expandedContent?: string;
  /** Vault chunks: the hit chunk's own [start, end) in the document's extracted text, when verified. */
  hitSpan?: { start: number; end: number } | null;
  /** Vault chunks: the verified surrounding span, or why there is none (passage-context-span.ts). */
  passageContext?: PassageContext;
  /** Sequential index of this chunk within its document; enables window expansion. */
  chunkIndex?: number;
  pageNumber?: number;
  sectionTitle?: string | null;
  locator?: string;
  /**
   * The Data Room artifact this chunk was cut from (`lumen_data_atoms
   * .source_id`), when the corpus records one. It is what resolves to a
   * canonical `cre_evidence_sources` row (retrieval-source-link), and so what
   * lets a passage be CITED rather than merely read — the executor's drafting
   * tools accept it back as `sources[].artifact_id` (ledger L154). Absent for
   * corpora with no artifact linkage; never guessed.
   */
  sourceArtifactId?: string | null;
  /**
   * Opaque passthrough of the originating row, set by corpora whose callers
   * need the full record back (the memory corpora carry every column here so
   * the memory shims can reconstruct their rich entry type — confidence,
   * importance, verification, timestamps — that the document fields above drop).
   * Reranking/MMR only reorder documents and compression is disabled for these
   * corpora, so this survives the pipeline untouched.
   */
  sourceRow?: Record<string, unknown>;
  /**
   * The index-time embedding for this candidate, carried straight out of the
   * vector store (the `embedding` column we already rank on) so MMR can measure
   * diversity without re-embedding the content via a separate OpenAI round-trip.
   * Only populated when MMR is requested (`needEmbeddings`); corpora that don't
   * expose a stored vector (e.g. project atoms via searchHybrid) leave it unset,
   * and MMR embeds just those stragglers.
   */
  embedding?: number[];
}

export interface RAGContext {
  documents: RetrievedDocument[];
  totalCandidates: number;
  retrievalStrategy: string;
  processingTimeMs: number;
  tokensUsed: number;
}

type VaultChunkRow = {
  chunk_id: string;
  document_id: string;
  program_id?: string;
  content_hash?: string;
  title: string | null;
  content: string | null;
  page_number: number | null;
  section_title: string | null;
  chunk_index: number | null;
  similarity: number;
  /** Stored index vector in pgvector text form ('[a,b,...]'); only selected when needEmbeddings. */
  embedding?: unknown;
  vaultPassageSnapshot?: VaultPassageSnapshot;
};

/** Corpus selection threaded through the strategy methods to searchInitial. */
type CorpusScope = {
  vaultRead?: VerifiedVaultRead;
  corpus?: 'vault' | 'rag_chunks' | 'client_memory' | 'project_memory';
  organizationId?: number;
  memory?: MemoryScope;
  /**
   * Fuse dense retrieval with a sparse full-text retrieval via RRF. Honoured
   * only by the vault and rag_chunks paths; the memory paths ignore it.
   */
  hybrid?: boolean;
  /**
   * Metadata pre-filters (document type / source / date range) applied in the
   * vault and rag_chunks SQL. Honoured only by those corpora; project atoms and
   * memory ignore them.
   */
  filters?: QueryFilters;
  sourceReadScope?: AdmittedAnaSourceReadScope;
  /**
   * Pull each candidate's stored embedding out of the vector search so MMR can
   * reuse it instead of re-embedding. Set only when the caller requested MMR,
   * so non-MMR queries don't pay to ship vector text they won't use.
   */
  needEmbeddings?: boolean;
};

const candidateOrganizationUuid = (options: RetrievalOptions): string | undefined =>
  options.artifactScope?.organizationUuid ?? options.organizationUuid;

function pinActorRetrievalOptions(options: RetrievalOptions): RetrievalOptions {
  if (!options.sourceReadScope) return options;
  if (options.artifactScope || (options.corpus && options.corpus !== 'vault') || options.persistCitations) {
    throw new Error('The admitted source programme scope requires the Vault corpus. Nothing was searched.');
  }
  const permitted = options.sourceReadScope.accessibleProgramIds;
  const explicit = options.filters?.allowedProgramIds;
  if (explicit !== undefined && !Array.isArray(explicit)) {
    throw new Error('The requested programme restriction could not be verified. Nothing was searched.');
  }
  return { ...options, sourceReadScope: pinRetrievalReadScope(options.sourceReadScope),
    filters: { ...options.filters, allowedProgramIds: explicit === undefined
      ? [...permitted] : permitted.filter(id => explicit.includes(id)) } };
}

function assertVaultSourceScope(read: VerifiedVaultRead, source?: AdmittedAnaSourceReadScope): void {
  if (source && (source.organizationId !== read.organizationId || source.userId !== read.userId ||
      source.programId !== read.programId || source.role !== read.verifiedScope.actor.role ||
      source.accessibleProgramIds.length !== read.verifiedScope.programIds.length ||
      source.accessibleProgramIds.some((id, index) => id !== read.verifiedScope.programIds[index]))) {
    throw new ProgramReadAccessError(403, 'PROJECT_SCOPE_UNVERIFIED',
      'The current source scope does not match the verified Vault scope. Nothing was searched.');
  }
}

function assertCandidateSnapshot(type: string, scope: AdmittedAnaSourceReadScope | undefined,
  candidates: RetrievedDocument[], rows: Array<{ id: string; document_id?: string; program_id?: string; content_hash?: string }>): void {
  if (type !== 'vault_chunk' || !scope) return;
  if (rows.length !== new Set(candidates.map(d => d.chunkId ?? d.id)).size) {
    throw new Error('Source access or identity changed during retrieval. Nothing was returned.');
  }
  for (const row of rows) {
    const candidate = candidates.find(d => (d.chunkId ?? d.id) === row.id);
    if (!candidate || candidate.documentId !== row.document_id || candidate.programId !== row.program_id ||
        candidate.contentHash !== row.content_hash || !/^[0-9a-f]{64}$/i.test(row.content_hash ?? '')) {
      throw new Error('The selected source identity changed during retrieval. Nothing was returned.');
    }
  }
}

function invalidVaultRow(): never {
  throw new ProgramReadAccessError(503, 'VAULT_RETRIEVAL_RECORD_INVALID',
    'The Vault passage record could not be verified. No passage content was supplied.');
}
function vaultText(value: unknown): string {
  if (typeof value !== 'string') return invalidVaultRow();
  return value;
}
function nullableVaultText(value: unknown): string | null {
  return value === null ? null : vaultText(value);
}
function vaultNumber(value: unknown): number {
  if (typeof value !== 'number' || !Number.isFinite(value)) return invalidVaultRow();
  return value;
}
function nullableVaultNumber(value: unknown): number | null {
  return value === null ? null : vaultNumber(value);
}
function readVaultPassageSnapshot(row: Record<string, unknown>): VaultPassageSnapshot {
  const hash = row.extracted_text_sha256;
  if (hash !== null && (typeof hash !== 'string' || !/^[0-9a-f]{64}$/.test(hash))) return invalidVaultRow();
  const coordinate = (value: unknown): number | null => {
    if (value === null) return null;
    if (typeof value !== 'number' || !Number.isSafeInteger(value)) return invalidVaultRow();
    return value;
  };
  return { extractedTextSha256: hash, charStart: coordinate(row.char_start), charEnd: coordinate(row.char_end) };
}
/** These are the columns selected by the one canonical Vault reader. */
function readVaultChunkRow(row: Record<string, unknown>): VaultChunkRow {
  return {
    chunk_id: vaultText(row.chunk_id), document_id: vaultText(row.document_id),
    program_id: row.program_id == null ? undefined : vaultText(row.program_id),
    content_hash: row.content_hash == null ? undefined : vaultText(row.content_hash),
    title: nullableVaultText(row.title), content: nullableVaultText(row.content),
    page_number: nullableVaultNumber(row.page_number),
    section_title: nullableVaultText(row.section_title),
    chunk_index: nullableVaultNumber(row.chunk_index), similarity: vaultNumber(row.similarity),
    // Preserve the existing parser's undefined/invalid-vector fallback for MMR.
    embedding: row.embedding,
    vaultPassageSnapshot: readVaultPassageSnapshot(row),
  };
}
type VaultCandidateRow = {
  id: string; document_id: string; program_id?: string; content_hash?: string;
  title: string; original_file_available: boolean;
  content: string | null; snapshot: VaultPassageSnapshot; inExtraction: boolean | null;
};
function readVaultCandidateRow(row: Record<string, unknown>): VaultCandidateRow {
  if (typeof row.original_file_available !== 'boolean') return invalidVaultRow();
  const snapshot = readVaultPassageSnapshot(row);
  const inExtraction = row.chunk_in_extraction;
  if (inExtraction !== null && typeof inExtraction !== 'boolean') return invalidVaultRow();
  if ((snapshot.extractedTextSha256 === null) !== (inExtraction === null)) return invalidVaultRow();
  return { id: vaultText(row.id), document_id: vaultText(row.document_id),
    program_id: row.program_id == null ? undefined : vaultText(row.program_id),
    content_hash: row.content_hash == null ? undefined : vaultText(row.content_hash),
    title: vaultText(row.title), original_file_available: row.original_file_available,
    content: nullableVaultText(row.chunk_text), snapshot, inExtraction };
}

/** Membership preserves legacy hit-only reads; only passage-context-span proves exact offsets. */
function currentVaultPassage(doc: RetrievedDocument, row: VaultCandidateRow): boolean {
  if (!row.content || doc.content !== row.content || row.inExtraction === false) return false;
  const pinned = doc.vaultPassageSnapshot;
  if (pinned) {
    if (pinned.extractedTextSha256 !== row.snapshot.extractedTextSha256 ||
        pinned.charStart !== row.snapshot.charStart || pinned.charEnd !== row.snapshot.charEnd) return false;
  } else if (doc.expandedContent || doc.compressedContent) {
    // Never invent the derivation basis of previously expanded/compressed text.
    return false;
  }
  return doc.passageContext?.status !== 'available' ||
    doc.passageContext.reference.extractedTextSha256 === row.snapshot.extractedTextSha256;
}
/**
 * A vault hit with its verified surrounding span (passage-context-span.ts).
 * No rows drops the candidate, as before: retaining the old chunk would defeat
 * a withdrawal confirmed after retrieval. Rows that do not verify leave the
 * hit's own content standing and say why; joined chunk text is never used.
 */
function withVaultSpan(doc: RetrievedDocument, rows: Record<string, unknown>[]): RetrievedDocument | null {
  if (rows.length === 0) return null;
  const chunks = rows.map(row => ({
    id: String(row.id ?? invalidVaultRow()),
    chunkIndex: vaultNumber(row.chunk_index),
    charStart: nullableVaultNumber(row.char_start),
    charEnd: nullableVaultNumber(row.char_end),
    text: nullableVaultText(row.chunk_text) ?? '',
  }));
  const textRow = rows.find(row => row.extracted_text !== null && row.extracted_text !== undefined);
  const { context, hitSpan } = buildPassageContext({
    documentId: doc.documentId ?? '',
    contentHash: doc.contentHash ?? '',
    extractedText: textRow ? vaultText(textRow.extracted_text) : null,
    hit: { chunkId: String(doc.chunkId ?? doc.id ?? ''), chunkIndex: doc.chunkIndex ?? -1 },
    chunks,
  });
  const hit: RetrievedDocument = { ...doc };
  delete hit.expandedContent;
  return { ...hit, hitSpan, passageContext: context, ...(context.status === 'available' ? { expandedContent: context.text } : {}) };
}

/** The request executor carries session variables and may be in autocommit.
 * Do not open or finish a caller's transaction to recover an optional index. */
async function optionalVaultSavepoint(client: TenantKeyQueryable): Promise<boolean> {
  try {
    await client.query('SAVEPOINT vault_dense_search');
    return true;
  } catch (error) {
    const failure = error as { code?: string; message?: string };
    if (failure.code === '25P01' && failure.message === 'SAVEPOINT can only be used in transaction blocks') return false;
    throw error;
  }
}

async function recoverVaultSavepoint(client: TenantKeyQueryable, savepoint: boolean): Promise<void> {
  if (!savepoint) return;
  await client.query('ROLLBACK TO SAVEPOINT vault_dense_search');
  await client.query('RELEASE SAVEPOINT vault_dense_search');
}

/**
 * Parse a pgvector value into a number[]. Without a registered pg type parser
 * the column arrives as the text form '[a,b,...]'; tolerate an already-parsed
 * numeric array too. Returns undefined on anything malformed so callers fall
 * back to embedding/lexical paths rather than ranking on a partial vector.
 */
export function parsePgVector(value: unknown): number[] | undefined {
  if (Array.isArray(value)) {
    return value.every(n => typeof n === 'number' && Number.isFinite(n))
      ? (value as number[])
      : undefined;
  }
  if (typeof value !== 'string' || value.length < 2) return undefined;
  const inner = value.charCodeAt(0) === 0x5b /* [ */ ? value.slice(1, -1) : value;
  if (!inner) return undefined;
  const parts = inner.split(',');
  const out = new Array<number>(parts.length);
  for (let i = 0; i < parts.length; i++) {
    const n = Number(parts[i]);
    if (!Number.isFinite(n)) return undefined;
    out[i] = n;
  }
  return out;
}

function buildLocator(row: VaultChunkRow): string | undefined {
  if (row.section_title && row.section_title.trim()) {
    return row.section_title.trim();
  }
  if (row.page_number !== null && row.page_number !== undefined) {
    return `p.${row.page_number}`;
  }
  return undefined;
}

/** Canonical dense Vault statement: hash only the materialized, limited candidates. */
// tenant-isolation-safe: scoped binds the organization UUID at $4 before ranking.
function vaultDensePassageSql(denseFilter: string, embeddingCol: string): string {
  return `
        WITH scoped AS MATERIALIZED (
          SELECT
            c.id, c.document_id, c.chunk_text, c.page_number, c.section_title,
            c.chunk_index, c.char_start, c.char_end, c.embedding, d.program_id, d.content_hash,
            COALESCE(d.document_title, d.file_name, '') ||
              CASE WHEN ${vaultBinaryAvailableSql('d')} THEN ''
              ELSE ' [original file unavailable; retained extracted data]' END AS title
          FROM vault.document_chunks c
          JOIN vault.documents d ON d.id = c.document_id
          WHERE c.embedding IS NOT NULL${denseFilter}
            AND d.deleted_at IS NULL
            AND ${vaultDataEligibleSql('d')}
            AND NOT ${supersededSql('d')}
            AND EXISTS (SELECT 1 FROM regulatory_programs p WHERE p.id = d.program_id AND p.organization_id = d.organization_id AND p.deleted_at IS NULL)
            -- Explicit tenant predicate. A document with a NULL organization_id is
            -- unattributable (migrations/20260905_vault_documents_organization_id.sql)
            -- and this predicate excludes it, which is the intended refusal: an
            -- orphan document belongs to no tenant and is returned to none.
            AND d.organization_id IN (SELECT o.id FROM organizations o WHERE o.uuid = $4::uuid)
        ), ranked AS MATERIALIZED (
        SELECT
          s.id AS chunk_id,
          s.document_id AS document_id,
          s.program_id::text AS program_id, s.content_hash,
          s.title AS title,
          s.chunk_text AS content,
          s.page_number AS page_number,
          s.section_title AS section_title,
          s.chunk_index AS chunk_index,
          s.char_start, s.char_end,
          ${embeddingCol.replace('c.embedding', 's.embedding')}
          1 - (s.embedding <=> $1::vector) AS similarity
        FROM scoped s
        -- (1 - sim) filter as a distance bound: 1 - dist > t  <=>  dist < 1 - t.
        -- $2 is cast explicitly: in "1 - $2" Postgres infers the parameter
        -- from the integer literal, and a float threshold like 0.65 then
        -- fails with 22P02 before the query ever runs.
        WHERE (s.embedding <=> $1::vector) < 1 - $2::float8
        ORDER BY s.embedding <=> $1::vector
        LIMIT $3
        )
        SELECT ranked.*,
               encode(sha256(convert_to(d.extracted_text, 'UTF8')), 'hex') AS extracted_text_sha256
          FROM ranked JOIN vault.documents d ON d.id = ranked.document_id
         ORDER BY ranked.similarity DESC
      `;
}

/** One vault chunk row as a retrieved passage. */
function vaultChunkToDoc(row: VaultChunkRow, withEmbedding?: boolean): RetrievedDocument {
  return {
    id: row.chunk_id,
    chunkId: row.chunk_id,
    documentId: row.document_id,
    programId: row.program_id,
    contentHash: row.content_hash,
    vaultPassageSnapshot: row.vaultPassageSnapshot,
    content: row.content || '',
    title: row.title || 'Untitled',
    atomType: 'vault_chunk',
    initialScore: Number(row.similarity),
    finalScore: Number(row.similarity),
    pageNumber: row.page_number ?? undefined,
    sectionTitle: row.section_title,
    chunkIndex: row.chunk_index ?? undefined,
    locator: buildLocator(row),
    embedding: withEmbedding ? parsePgVector(row.embedding) : undefined,
  };
}

/** RFC-4122 shape. Guards the `::uuid` casts on the vault retrieval path so a
 *  malformed org id is an authorization refusal, not a 22P02 query failure. */
const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

/*
 * The tenant a retrieval may read is the REQUEST SCOPE's, not the caller's
 * argument (D3, docs/evidence/D3/2026-09-24-rag-pipeline-tenant/).
 * withTenantContext writes its uuid into app.current_org_id, the GUC vault RLS
 * keys on, and the vault arm's predicate is the same option — so a uuid that is
 * not the session's would override the scope the auth boundary opened. The
 * check lives in server/db/currentTenant.ts (assertTenantIsCurrent), shared with
 * the atom search this pipeline's project arm ends in; it was defined here
 * first, and moved there so there is one.
 */
async function withTenantContext<T>(
  pool: pg.Pool,
  organizationUuid: string | undefined,
  fn: (client: pg.PoolClient) => Promise<T>
): Promise<T> {
  const client = await pool.connect();
  try {
    // The GUC below decides what vault RLS admits, so the uuid must be the
    // session's before it is written.
    await assertTenantIsCurrent(client, { organizationUuid });
    await client.query('BEGIN');
    if (organizationUuid) {
      await client.query("SELECT set_config('app.current_org_id', $1, true)", [organizationUuid]);
    }
    const result = await fn(client);
    await client.query('COMMIT');
    return result;
  } catch (error) {
    try {
      await client.query('ROLLBACK');
    } catch {
      // ignore rollback errors
    }
    throw error;
  } finally {
    client.release();
  }
}

// ═══════════════════════════════════════════════════════════════════════════
//                          ADVANCED RAG PIPELINE
// ═══════════════════════════════════════════════════════════════════════════

export class AdvancedRAGPipeline {
  private embeddingService: EnhancedEmbeddingService;
  private aiRouter: AIProviderRouter;
  private pool: pg.Pool;
  private openai: any;
  // Reranking strategy. Defaults to the LLM-as-judge provider (prior behavior);
  // swaps to a cross-encoder when RAG_RERANKER_* is configured. See rag-reranker.ts.
  private reranker: Reranker;

  // In-memory TTL + LRU cache for the auxiliary reasoning calls (HyDE, query
  // expansion, reranking, compression). These repeat verbatim across similar
  // queries, so caching them cuts the 4+N per-query LLM round-trips. Eviction is
  // least-recently-used (a live hit is re-inserted to refresh recency). The
  // final grounded answer is deliberately never cached.
  private llmCallCache = new Map<string, { value: AIResponse; expiresAt: number }>();
  private readonly llmCacheTtlMs = 60 * 60 * 1000; // 1 hour
  private readonly llmCacheMaxEntries = 500;

  constructor(pool: pg.Pool) {
    this.pool = pool;
    this.embeddingService = getEmbeddingService(pool);
    this.aiRouter = getAIRouter(pool);

    // OpenAI client wiring removed — this pipeline now goes through
    // aiRouter for completions. Keep the field as an any-shaped stub so
    // legacy references still compile.
    this.openai = null;

    // LLM-judge reranks route through the cached AI router so identical rerank
    // calls reuse the prior result; a cross-encoder provider (if configured)
    // ignores the route fn and calls its own HTTP endpoint.
    this.reranker = getReranker(req => this.routeCached(req));

    console.log('✅ Advanced RAG Pipeline initialized');
  }

  /** Admit the server-only composition before any provider can see the query. */
  private async admitVaultRead(options: RetrievalOptions): Promise<VerifiedVaultRead | undefined> {
    const read = options.vaultRead;
    if (!read) {
      await this.refreshSourceRead(undefined, options.sourceReadScope);
      return undefined;
    }
    if (options.artifactScope || (options.corpus && options.corpus !== 'vault') || options.persistCitations) {
      throw new ProgramReadAccessError(403, 'VAULT_READ_SCOPE_ONLY',
        'The verified Vault read scope cannot authorize another corpus or citation writes.');
    }
    if (options.organizationId !== undefined && options.organizationId !== read.organizationId) {
      throw new ProgramReadAccessError(403, 'PROJECT_SCOPE_UNVERIFIED', 'The verified Vault scope names a different organization.');
    }
    assertVerifiedProgramScope(read.sqlClient, read, read.verifiedScope);
    const source = options.sourceReadScope;
    assertVaultSourceScope(read, source);
    if (!isTenantUuid(options.organizationUuid)) {
      throw new ProgramReadAccessError(403, 'VAULT_TENANT_REQUIRED', 'A verified tenant identity is required to read Vault passages.');
    }
    await requireProgramScopeStillCurrent(read.sqlClient, read, read.verifiedScope);
    await this.refreshSourceRead(read, source);
    return read;
  }

  private async refreshSourceRead(read: VerifiedVaultRead | undefined, source?: AdmittedAnaSourceReadScope): Promise<void> {
    if (!source) return;
    if (read) await revalidateAnaSourceReadScope(read.sqlClient, source);
    else await withRetrievalReadScope(source, async () => undefined);
  }

  private async selectCandidates(
    candidates: RetrievedDocument[], limit: number, options: RetrievalOptions,
    embeddingService: EnhancedEmbeddingService,
  ): Promise<RetrievedDocument[]> {
    if (options.useMmr && candidates.length > limit) {
      await this.refreshVaultRead(options.vaultRead);
      return this.applyMmr(candidates, limit, options.mmrLambda || 0.7, embeddingService);
    }
    return candidates.slice(0, limit);
  }

  private embeddingsForVaultRead(read?: VerifiedVaultRead): EnhancedEmbeddingService {
    return read ? getEmbeddingService(read.sqlClient) : this.embeddingService;
  }

  private async refreshVaultRead(read?: VerifiedVaultRead): Promise<void> {
    if (read) await requireProgramScopeStillCurrent(read.sqlClient, read, read.verifiedScope);
  }

  private async emptyVaultContext(
    read: VerifiedVaultRead | undefined, options: RetrievalOptions, startTime: number,
  ): Promise<RAGContext | null> {
    if (!read || read.verifiedScope.programIds.length > 0) return null;
    await this.refreshVaultRead(read);
    return { documents: [], totalCandidates: 0, retrievalStrategy: options.strategy,
      processingTimeMs: Date.now() - startTime, tokensUsed: 0 };
  }

  private async validateRetrievalTenant(options: RetrievalOptions, read?: VerifiedVaultRead): Promise<void> {
    await assertTenantIsCurrent(read ? read.sqlClient : this.pool, {
      organizationUuid: candidateOrganizationUuid(options),
      organizationId: read ? read.organizationId : options.organizationId,
    });
  }

  private async withVaultReadExecutor<T>(
    organizationUuid: string | undefined, read: VerifiedVaultRead | undefined,
    source: AdmittedAnaSourceReadScope | undefined,
    work: (client: TenantKeyQueryable) => Promise<T>,
  ): Promise<T> {
    if (!read) {
      if (!source) return withTenantContext(this.pool, organizationUuid, work);
      return withRetrievalReadScope(source, async q => {
        const { rows } = await q.query('SELECT id FROM organizations WHERE id=$1 AND uuid=$2::uuid',
          [source.organizationId, organizationUuid ?? null]);
        if (rows.length !== 1 || Number(rows[0].id) !== source.organizationId) {
          throw new Error('The source organization identity could not be verified. Nothing was searched.');
        }
        const result = await work(q);
        await revalidateAnaSourceReadScope(q as RequestSqlClient, source);
        return result;
      });
    }
    assertVerifiedProgramScope(read.sqlClient, read, read.verifiedScope);
    await assertTenantIsCurrent(read.sqlClient, { organizationUuid, organizationId: read.organizationId });
    await requireProgramScopeStillCurrent(read.sqlClient, read, read.verifiedScope);
    await this.refreshSourceRead(read, source);
    try {
      const result = await work(read.sqlClient);
      await this.refreshVaultRead(read);
      await this.refreshSourceRead(read, source);
      return result;
    } catch (error) {
      if (error instanceof ProgramReadAccessError) throw error;
      throw new ProgramReadAccessError(503, 'VAULT_RETRIEVAL_UNAVAILABLE',
        'Vault passages could not be read. No passage content was supplied.');
    }
  }

  /**
   * Main retrieval function with configurable strategies
   */

  /**
   * Step 1 of retrieve(): choose the initial candidate set by strategy.
   *
   * Extracted from retrieve() verbatim — every branch, every `limit`
   * multiplier, every tokensUsed accumulation, and the 'advanced' branch's
   * assignment of retrievalStrategy are unchanged. retrieve() reached 101 lines
   * against a 100-line limit when the vault tenant-scoping landed, and this
   * switch is the one self-contained step in it: given the strategy it returns
   * candidates, and nothing else in the method reaches into it.
   */
  private async retrieveCandidates(
    deps: StrategyDeps,
    query: string,
    limit: number,
    strategy: RetrievalOptions['strategy'],
  ): Promise<{ candidates: RetrievedDocument[]; tokensUsed: number; retrievalStrategy: string }> {
    let candidates: RetrievedDocument[];
    let tokensUsed = 0;
    // Same free-form label retrieve() kept: defaults to the requested strategy,
    // and only the composite branch overwrites it.
    let retrievalStrategy: string = strategy;

      switch (strategy) {
        case 'hyde': {
          const result = await hydeRetrieval(deps, query, limit * 3);
          candidates = result.documents;
          tokensUsed += result.tokensUsed;
          break;
        }

        case 'multi_query': {
          const result = await multiQueryRetrieval(deps, query, limit * 3);
          candidates = result.documents;
          tokensUsed += result.tokensUsed;
          break;
        }

        case 'step_back': {
          const result = await stepBackRetrieval(deps, query, limit * 3);
          candidates = result.documents;
          tokensUsed += result.tokensUsed;
          break;
        }

        case 'decompose': {
          const result = await decomposeRetrieval(deps, query, limit * 3);
          candidates = result.documents;
          tokensUsed += result.tokensUsed;
          break;
        }

        case 'advanced': {
          // Combine HyDE + Multi-Query
          const [hyde, multi] = await Promise.all([
            hydeRetrieval(deps, query, limit * 2),
            multiQueryRetrieval(deps, query, limit * 2),
          ]);
          candidates = mergeByMaxScore([...hyde.documents, ...multi.documents]);
          tokensUsed += hyde.tokensUsed + multi.tokensUsed;
          retrievalStrategy = 'advanced';
          break;
        }

        case 'basic':
        default:
          candidates = await deps.search(query, limit * 3);
          break;
      }

    return { candidates, tokensUsed, retrievalStrategy };
  }

  async retrieve(
    query: string,
    options: RetrievalOptions = { strategy: 'basic' }
  ): Promise<RAGContext> {
    options = pinActorRetrievalOptions(options);
    // Every arm below takes its tenant from these options; refuse any that is
    // not the session's before one of them runs.
    const vaultRead = await this.admitVaultRead(options);
    await this.validateRetrievalTenant(options, vaultRead);
    const startTime = Date.now();
    const limit = options.limit || 10;
    const threshold = options.threshold || 0.5;
    const artifactScope = options.artifactScope;
    const scope: CorpusScope = {
      vaultRead,
      corpus: options.corpus,
      organizationId: options.organizationId,
      memory: options.memoryScope,
      // Only carry stored vectors out of the search when MMR will consume them.
      needEmbeddings: !!options.useMmr,
      hybrid: !!options.useHybrid,
      // Explicit filters apply on the chunk corpora regardless of self-query;
      // the self-query step below augments these in place.
      filters: options.filters,
      sourceReadScope: options.sourceReadScope,
    };

    let candidates: RetrievedDocument[];
    let tokensUsed = 0;

    const emptyContext = await this.emptyVaultContext(vaultRead, options, startTime);
    if (emptyContext) return emptyContext;
    const embeddingService = this.embeddingsForVaultRead(vaultRead);

    // Primitives the query-transform strategies fan out through, bound to this
    // call's scope (tenant, threshold, corpus). See rag-retrieval-strategies.ts.
    const deps: StrategyDeps = {
      route: req => this.routeCached(req),
      embedBatch: queries => embeddingService.embedBatch(queries, 'text-embedding-3-small'),
      search: (q, l) => this.searchInitial(q, l, threshold, options.organizationUuid, artifactScope, scope),
    };

    // Step 0: Self-querying. Extract metadata constraints from the question and
    // merge them under any explicit filters (explicit wins), then pre-filter the
    // chunk-corpus SQL via scope.filters. deps.search closes over `scope`, so
    // setting it here applies to every strategy's retrieval below.
    if (options.useSelfQuery) {
      const extracted = await extractQueryFilters(deps.route, query);
      tokensUsed += extracted.tokensUsed;
      scope.filters = mergeFilters(extracted.filters, options.filters);
    }

    // Step 1: Initial retrieval based on strategy (see retrieveCandidates).
    const initial = await this.retrieveCandidates(deps, query, limit, options.strategy);
    candidates = initial.candidates;
    tokensUsed += initial.tokensUsed;
    // Descriptive label for RAGContext.retrievalStrategy (free-form string).
    // Assigned once, read once, so it is a const now that the switch that used
    // to set it lives in retrieveCandidates.
    const retrievalStrategy: string = initial.retrievalStrategy;

    const totalCandidates = candidates.length;

    // Retrieval is a snapshot. Recheck after every asynchronous processing step
    // before the next provider sees candidate text; no cache bypasses withdrawal.
    candidates = await this.revalidateCandidates(candidates, options);

    // Step 2: reranking via the configured provider (LLM-judge by default,
    // cross-encoder when RAG_RERANKER_* is set).
    if (options.useReranking && candidates.length > 0) {
      await this.refreshVaultRead(vaultRead);
      const rerankResult = await this.applyReranker(query, candidates, options.governedVerdict === true);
      candidates = rerankResult.documents;
      tokensUsed += rerankResult.tokensUsed;
    }

    // Step 3: MMR for diversity
    candidates = await this.revalidateCandidates(candidates, options);
    candidates = await this.selectCandidates(candidates, limit, options, embeddingService);

    // Step 3.5: Small-to-big context expansion (ranked on small chunks, read on
    // a wider window). Runs before compression so compression extracts from the
    // expanded window.
    if (options.useContextExpansion && candidates.length > 0) {
      candidates = await this.expandContext(
        candidates,
        options.contextWindow ?? 1,
        options.organizationUuid,
        options.organizationId,
        { filters: options.filters, sourceReadScope: options.sourceReadScope, vaultRead },
      );
    }

    // Step 4: Contextual compression
    candidates = await this.revalidateCandidates(candidates, options);
    if (options.useCompression && candidates.length > 0) {
      await this.refreshVaultRead(vaultRead);
      const compressionResult = await this.compressContexts(query, candidates);
      candidates = compressionResult.documents;
      tokensUsed += compressionResult.tokensUsed;
    }

    candidates = await this.revalidateCandidates(candidates, options);
    await this.refreshVaultRead(vaultRead);
    return {
      documents: candidates,
      totalCandidates,
      retrievalStrategy,
      processingTimeMs: Date.now() - startTime,
      tokensUsed,
    };
  }

  /**
   * Batch by corpus, bind the tenant/project again, and fail closed on lookup
   * errors. A missing row is no longer usable grounding. Memory entries have
   * their own lifecycle and are not document identities; public RAG guidance
   * must be verified by a row whose organization_id is NULL.
   *
   * These are point-in-time checks, not a cancellation protocol for an already
   * dispatched provider request. A later disposition cannot recall its input.
   */
  private async revalidateCandidates(
    documents: RetrievedDocument[], options: RetrievalOptions,
  ): Promise<RetrievedDocument[]> {
    const vaultRead = await this.admitVaultRead(options);
    const eligible = new Map<string, { documentId?: string; available: boolean; title: string; vault?: VaultCandidateRow }>();
    const uuid = candidateOrganizationUuid(options);
    await this.validateRetrievalTenant(options, vaultRead);
    const groups = ['vault_chunk', 'rag_chunk', 'project_atom'] as const;
    for (const type of groups) {
      const candidates = documents.filter(d => d.atomType === type);
      if (!candidates.length) continue;
      const ids = [...new Set(candidates.map(d => d.chunkId ?? d.id))];
      let rows: Array<{ id: string; document_id?: string; program_id?: string; content_hash?: string; original_file_available: boolean; title: string }>;
      let vaultRows: VaultCandidateRow[] | undefined;
      if (type === 'vault_chunk') {
        if (!isTenantUuid(uuid)) continue;
        const params: unknown[] = [ids, uuid];
        const filter = buildDocFilterClause(options.filters, params, VAULT_FILTER_COLUMNS, vaultRead?.verifiedScope.programIds);
        vaultRows = await this.withVaultReadExecutor(uuid, vaultRead, options.sourceReadScope, async client => (await client.query(
          `SELECT c.id::text AS id, d.id::text AS document_id, d.program_id::text AS program_id, d.content_hash,
                  c.chunk_text, c.char_start, c.char_end,
                  encode(sha256(convert_to(d.extracted_text, 'UTF8')), 'hex') AS extracted_text_sha256,
                  CASE WHEN d.extracted_text IS NULL THEN NULL
                    ELSE COALESCE(strpos(d.extracted_text, c.chunk_text) > 0, FALSE) END AS chunk_in_extraction,
                  COALESCE(d.document_title, d.file_name, '') AS title,
                  ${vaultBinaryAvailableSql('d')} AS original_file_available
             FROM vault.document_chunks c JOIN vault.documents d ON d.id = c.document_id
            WHERE c.id::text = ANY($1::text[]) AND d.deleted_at IS NULL ${filter}
              AND d.organization_id IN (SELECT o.id FROM organizations o WHERE o.uuid=$2::uuid)
              AND EXISTS (SELECT 1 FROM regulatory_programs p WHERE p.id=d.program_id
                AND p.organization_id=d.organization_id AND p.deleted_at IS NULL)
              AND ${vaultDataEligibleSql('d')} AND NOT ${supersededSql('d')}`,
          params,
        )).rows.map(readVaultCandidateRow));
        rows = vaultRows;
      } else if (type === 'rag_chunk') {
        // A missing tenant key means explicitly public guidance, never all orgs.
        ({ rows } = await this.pool.query(
          `SELECT c.id::text AS id, d.id::text AS document_id, COALESCE(d.title,'') AS title,
                  ${ragOriginalFileAvailableSql('d')} AS original_file_available
             FROM rag_chunks c JOIN rag_documents d ON d.id=c.document_id
            WHERE c.id::text=ANY($1::text[]) AND ${ragDataEligibleSql('d')}
              AND (d.organization_id IS NULL OR d.organization_id=$2::int
                OR d.organization_id IN (SELECT o.id FROM organizations o WHERE o.uuid=$3::uuid))`,
          [ids, options.organizationId ?? null, isTenantUuid(uuid) ? uuid : null],
        ));
      } else {
        if (!isTenantUuid(uuid)) continue;
        const project = options.artifactScope?.projectId;
        ({ rows } = await this.pool.query(
          `SELECT a.id::text AS id, COALESCE(a.title,'') AS title,
                  ${atomOriginalFileAvailableSql('a')} AS original_file_available
             FROM lumen_data_atoms a
            WHERE a.id::text=ANY($1::text[])
              AND a.organization_id IN (SELECT o.id FROM organizations o WHERE o.uuid=$2::uuid)
              AND ${atomDataEligibleSql('a')}
              AND ($3::int IS NULL OR (a.source_type IN ('artifact','data_room_upload')
                AND a.source_id IN (SELECT artifact_id FROM concept2cure_artifacts
                  WHERE project_id=$3 AND organization_id=a.organization_id)))`,
          [ids, uuid, project == null ? null : Number(project)],
        ));
      }
      assertCandidateSnapshot(type, options.sourceReadScope, candidates, rows);
      for (const row of rows) {
        eligible.set(`${type}:${row.id}`, {
          documentId: row.document_id, available: row.original_file_available === true,
          title: String(row.title ?? ''),
          vault: vaultRows?.find(candidate => candidate.id === row.id),
        });
      }
    }
    await this.refreshVaultRead(vaultRead);
    return documents.flatMap(doc => {
      if (doc.atomType === 'client_memory' || doc.atomType === 'project_memory') return [doc];
      const row = eligible.get(`${doc.atomType}:${doc.chunkId ?? doc.id}`);
      if (!row || (doc.documentId && row.documentId !== doc.documentId)) return [];
      if (row.vault && !currentVaultPassage(doc, row.vault)) return [];
      return [{ ...doc, ...(row.vault ? { vaultPassageSnapshot: row.vault.snapshot } : {}),
        originalFileAvailable: row.available, title:
        (row.title || 'Untitled') + (row.available ? '' : ' [original file unavailable; retained extracted data]') }];
    });
  }

  /**
   * Initial-retrieval router. Picks project-scoped (lumen_data_atoms via the
   * search_atoms_hybrid SQL function) when artifactScope is provided, falls
   * back to vault chunks otherwise. All higher-level strategies (HyDE,
   * multi_query, basic) call through this so a single project filter
   * propagates through the whole pipeline.
   */
  private async searchInitial(
    query: string,
    limit: number,
    threshold: number,
    organizationUuid?: string,
    artifactScope?: RetrievalOptions['artifactScope'],
    scope?: CorpusScope
  ): Promise<RetrievedDocument[]> {
    if (artifactScope) {
      return this.searchProjectAtoms(query, limit, threshold, artifactScope);
    }
    if (scope?.corpus === 'rag_chunks') {
      return this.searchRagChunksSimilar(
        query,
        limit,
        threshold,
        scope.organizationId,
        scope.needEmbeddings,
        scope.hybrid,
        scope.filters
      );
    }
    if (scope?.corpus === 'client_memory') {
      return this.searchClientMemorySimilar(query, limit, threshold, scope);
    }
    if (scope?.corpus === 'project_memory') {
      return this.searchProjectMemorySimilar(query, limit, threshold, scope);
    }
    return this.searchVaultSimilar(
      query,
      limit,
      threshold,
      organizationUuid,
      scope?.needEmbeddings,
      scope?.hybrid,
      scope?.filters,
      scope?.vaultRead,
      scope?.sourceReadScope,
    );
  }

  /**
   * Project-scoped initial retrieval using the same hybrid (vector + BM25)
   * path as enhancedEmbeddingService.searchHybrid, with the project_id
   * filter pushed into SQL so cross-project chunks never appear in the
   * candidate set. Maps results into RetrievedDocument so downstream
   * reranking / MMR / compression all work transparently.
   */
  private async searchProjectAtoms(
    query: string,
    limit: number,
    threshold: number,
    artifactScope: NonNullable<RetrievalOptions['artifactScope']>
  ): Promise<RetrievedDocument[]> {
    // No floor here: the pipeline applies its own threshold to the combined score below.
    const hits = await this.embeddingService.searchHybrid(query, {
      limit,
      semanticWeight: 0.7,
      organizationUuid: artifactScope.organizationUuid,
      projectId: String(artifactScope.projectId),
    });
    return hits
      .filter(h => Number.isFinite(h.score) && h.score >= threshold)
      .map(h => ({
        id: h.id,
        chunkId: h.id,
        content: h.content || '',
        title: h.title || 'Untitled',
        atomType: 'project_atom',
        initialScore: h.score,
        finalScore: h.score,
        // Kept so the passage can be cited back to its Data Room source; the
        // hybrid search already carries it, this map used to drop it.
        sourceArtifactId: h.sourceId ?? null,
      }));
  }

  /**
   * LLM-based reranking (LLM-as-judge).
   *
   * An LLM scores each candidate's relevance to the query. This is NOT a
   * cross-encoder model and performs no cross-attention; it is a prompted
   * relevance score combined with the embedding score. Cheap to run, but
   * non-deterministic at temperature > 0 (we use 0 here for stability).
   */
  private async applyReranker(
    query: string,
    documents: RetrievedDocument[],
    governedVerdict = false
  ): Promise<{ documents: RetrievedDocument[]; tokensUsed: number }> {
    if (documents.length === 0) {
      return { documents: [], tokensUsed: 0 };
    }

    let result;
    try {
      result = await this.reranker.score(
        query,
        documents.map(d => ({ title: d.title, content: d.content })),
        { governedVerdict }
      );
    } catch (error) {
      // For a governed verdict the failure is the caller's to report.
      if (governedVerdict) throw error;
      // Otherwise a reranker failure must never break retrieval — keep the embedding order.
      console.warn('[RAG] reranker failed; keeping embedding order:', this.reranker.name, error);
      return { documents, tokensUsed: 0 };
    }

    // Defensive: a provider that returns the wrong count can't be trusted to
    // align with documents, so fall back rather than mis-rank.
    if (result.scores.length !== documents.length) {
      if (governedVerdict) {
        throw new Error(
          `reranker "${this.reranker.name}" returned ${result.scores.length} scores for ${documents.length} docs`
        );
      }
      console.warn(
        `[RAG] reranker "${this.reranker.name}" returned ${result.scores.length} scores for ${documents.length} docs; keeping embedding order`
      );
      return { documents, tokensUsed: result.tokensUsed };
    }

    // Combine the rerank score with the embedding score (same blend as before),
    // preserving every other field on the document (embedding, sourceRow, …).
    const reranked = documents.map((doc, idx) => {
      const rerankScore = result.scores[idx];
      return {
        ...doc,
        rerankScore,
        finalScore: (doc.initialScore + rerankScore) / 2,
      };
    });

    reranked.sort((a, b) => b.finalScore - a.finalScore);

    return { documents: reranked, tokensUsed: result.tokensUsed };
  }

  /**
   * Maximal Marginal Relevance for diversity.
   *
   * Diversity is measured as cosine similarity in embedding space (the same
   * space retrieval ranks in), not word overlap. Vectors are reused from the
   * vector store where the candidates were just retrieved (carried on
   * `RetrievedDocument.embedding`); only candidates that arrived without one are
   * embedded via the embedding service. If that embedding fails we fall back to
   * lexical Jaccard similarity so MMR still degrades gracefully.
   */
  private async applyMmr(
    documents: RetrievedDocument[],
    limit: number,
    lambda: number,
    embeddingService: EnhancedEmbeddingService = this.embeddingService
  ): Promise<RetrievedDocument[]> {
    if (documents.length <= limit) return documents;

    // Reuse the index-time vectors carried out of the vector store; only embed
    // the stragglers (e.g. project atoms via searchHybrid) that didn't carry
    // one. This avoids re-embedding the whole candidate set — those contents are
    // never query cache hits, so the old path paid a full OpenAI batch call on
    // every MMR query.
    const vectors: Array<number[] | null> = documents.map(d => d.embedding ?? null);
    const missing: number[] = [];
    for (let i = 0; i < vectors.length; i++) {
      if (!vectors[i]) missing.push(i);
    }
    if (missing.length > 0) {
      try {
        const embedded = await embeddingService.embedBatch(
          missing.map(i => documents[i].content || ''),
          'text-embedding-3-small'
        );
        missing.forEach((docIdx, k) => {
          vectors[docIdx] = embedded[k]?.embedding ?? null;
        });
      } catch (error) {
        console.warn(
          '[RAG] MMR embedding failed for uncarried candidates, using lexical fallback:',
          error
        );
      }
    }

    // Normalize once so each pairwise diversity check is a single dot product
    // rather than recomputing both vector norms on every comparison.
    const unit: Array<number[] | null> = vectors.map(v => (v ? this.normalize(v) : null));

    const similarity = (i: number, j: number): number => {
      const a = unit[i];
      const b = unit[j];
      if (a && b) {
        return this.dotProduct(a, b);
      }
      return this.calculateTextSimilarity(documents[i].content, documents[j].content);
    };

    const selectedIdx: number[] = [];
    const remainingIdx = documents.map((_, i) => i);

    while (selectedIdx.length < limit && remainingIdx.length > 0) {
      let bestPos = 0;
      let bestScore = -Infinity;

      for (let pos = 0; pos < remainingIdx.length; pos++) {
        const i = remainingIdx[pos];
        const relevance = documents[i].finalScore;

        // Diversity component: max similarity to anything already selected.
        let maxSimilarity = 0;
        for (const j of selectedIdx) {
          maxSimilarity = Math.max(maxSimilarity, similarity(i, j));
        }

        const mmrScore = lambda * relevance - (1 - lambda) * maxSimilarity;
        if (mmrScore > bestScore) {
          bestScore = mmrScore;
          bestPos = pos;
        }
      }

      selectedIdx.push(remainingIdx[bestPos]);
      remainingIdx.splice(bestPos, 1);
    }

    return selectedIdx.map(i => documents[i]);
  }

  /**
   * Small-to-big context expansion. Replaces each vault / rag_chunks result's
   * text with the chunk plus its ±window neighbours in the same document, so
   * generation sees the surrounding context the precise chunk omits (the chunk
   * stays the unit we *rank* on; the window is the unit we *read*). Results
   * without a chunk index (project atoms, memory) pass through unchanged, and a
   * missing or unreadable window drops the candidate: retaining the old chunk
   * would defeat a withdrawal confirmed after initial retrieval. Both windows
   * are backed by a (document_id, chunk_index) index.
   */
  private async expandContext(
    documents: RetrievedDocument[],
    window: number,
    organizationUuid?: string,
    organizationId?: number,
    sourceOptions: { filters?: QueryFilters; sourceReadScope?: AdmittedAnaSourceReadScope; vaultRead?: VerifiedVaultRead } = {},
  ): Promise<RetrievedDocument[]> {
    const { filters, sourceReadScope, vaultRead } = sourceOptions;
    if (window <= 0) return documents;
    const expanded = await Promise.all(
      documents.map(async doc => {
        if (doc.chunkIndex == null || !doc.documentId) return doc;
        const lo = doc.chunkIndex - window;
        const hi = doc.chunkIndex + window;
        try {
          let texts: string[];
          if (doc.atomType === 'vault_chunk') {
            return await this.withVaultReadExecutor(organizationUuid, vaultRead, sourceReadScope, async client => {
              const params: unknown[] = [doc.documentId, lo, hi, organizationUuid ?? null, doc.chunkId ?? doc.id ?? null];
              const filter = buildDocFilterClause(filters, params, VAULT_FILTER_COLUMNS, vaultRead?.verifiedScope.programIds);
              const identity = sourceReadScope || doc.contentHash
                ? `AND d.content_hash = $${params.push(doc.contentHash ?? '')}` : '';
              // Tenant, actor and exact source constraints precede the window.
              // The document text rides on the hit's row only, so the span is
              // cut from the same snapshot the neighbours were read in.
              const { rows } = await client.query(
                `SELECT c.id, c.chunk_index, c.char_start, c.char_end, c.chunk_text,
                        CASE WHEN c.id::text = $5::text THEN d.extracted_text END AS extracted_text
                   FROM vault.document_chunks c
                   JOIN vault.documents d ON d.id = c.document_id
                 WHERE c.document_id = $1 AND c.chunk_index BETWEEN $2 AND $3
                   AND d.deleted_at IS NULL AND ${vaultDataEligibleSql('d')} ${filter} ${identity}
                   AND d.organization_id IN (SELECT o.id FROM organizations o WHERE o.uuid=$4::uuid)
                   AND EXISTS (SELECT 1 FROM regulatory_programs p WHERE p.id=d.program_id
                     AND p.organization_id=d.organization_id AND p.deleted_at IS NULL)
                   AND NOT ${supersededSql('d')}
                 ORDER BY c.chunk_index`,
                params,
              );
              return withVaultSpan(doc, rows);
            });
          } else if (doc.atomType === 'rag_chunk') {
            // rag_chunks has no RLS; permit explicit public guidance or the
            // supplied integer/verified UUID tenant, even without prior retrieval.
            const { rows } = await this.pool.query<{ content: string | null }>(
              `SELECT rc.content FROM rag_chunks rc
               JOIN rag_documents rd ON rd.id = rc.document_id
               WHERE rc.document_id = $1 AND rc.chunk_index BETWEEN $2 AND $3
                 AND (rd.organization_id IS NULL OR rd.organization_id = $4::int
                   OR rd.organization_id IN (SELECT o.id FROM organizations o WHERE o.uuid = $5::uuid))
                 AND ${ragDataEligibleSql('rd')}
               ORDER BY rc.chunk_index`,
              [doc.documentId, lo, hi, organizationId ?? null,
                isTenantUuid(organizationUuid) ? organizationUuid : null]
            );
            texts = rows.map(r => r.content || '').filter(Boolean);
          } else {
            return doc;
          }
          if (!texts.length) return null;
          // Only annotate when the window actually added neighbours.
          return texts.length > 1 ? { ...doc, expandedContent: texts.join('\n\n') } : doc;
        } catch (error) {
          if (sourceReadScope || vaultRead) throw error;
          console.warn('[RAG] context expansion unavailable; refusing the stale chunk:', error);
          return null;
        }
      })
    );
    return expanded.filter((doc): doc is RetrievedDocument => doc !== null);
  }

  /**
   * Contextual compression - extract relevant passages
   */
  private async compressContexts(
    query: string,
    documents: RetrievedDocument[]
  ): Promise<{ documents: RetrievedDocument[]; tokensUsed: number }> {
    let totalTokens = 0;

    const compressedDocs = await Promise.all(
      documents.map(async doc => {
        // Compress the expanded window when present (small-to-big), else the chunk.
        const text = doc.expandedContent || doc.content;
        if (text.length < 500) {
          // Too short to compress
          return { ...doc, compressedContent: text };
        }

        const compressResponse = await this.routeCached({
          taskType: 'document_analysis',
          messages: [
            {
              role: 'system',
              content: `Extract ONLY the passages from the document that are directly relevant to answering the query. Include exact quotes with context. If nothing is relevant, respond with "NO_RELEVANT_CONTENT".`,
            },
            {
              role: 'user',
              content: `Query: "${query}"\n\nDocument:\n${text}`,
            },
          ],
          maxTokens: 400,
          temperature: 0,
        });

        totalTokens += compressResponse.usage.totalTokens;

        const compressed = compressResponse.content;
        if (compressed === 'NO_RELEVANT_CONTENT') {
          return { ...doc, compressedContent: '', finalScore: doc.finalScore * 0.5 };
        }

        return { ...doc, compressedContent: compressed };
      })
    );

    // Filter out documents with no relevant content
    const filtered = compressedDocs.filter(d => d.compressedContent !== '');

    return {
      documents: filtered,
      tokensUsed: totalTokens,
    };
  }

  /** The query as a pgvector literal, or null when no embedder will embed it (no key, or egress refused). */
  private async queryVectorOrNull(query: string, embeddingService = this.embeddingService): Promise<string | null> {
    try {
      const queryResult = await embeddingService.embed(query, 'text-embedding-3-small');
      return `[${queryResult.embedding.join(',')}]`;
    } catch (error) {
      console.warn(
        '[RAG] vault query not embedded; answering from the text index alone:',
        error instanceof Error ? error.message : String(error),
      );
      return null;
    }
  }

  /**
   * The vault's full-text arm over vault.document_chunks.chunk_text (GIN index,
   * migrations/20260905b_vault_document_chunks.sql). Two uses:
   *   - the sparse half of hybrid retrieval (keyless false): every term, scores
   *     left to reciprocal-rank fusion;
   *   - the whole search when there is no query vector (keyless true): ANY of
   *     the terms, ranked by ts_rank_cd normalised to 0..1, each hit marked
   *     lexicalOnly. A chunk written without an embedding is found either way.
   */
  private async vaultLexicalArm(
    client: TenantKeyQueryable,
    args: {
      query: string;
      limit: number;
      organizationUuid: string;
      filters?: QueryFilters;
      keyless: boolean;
      needEmbeddings?: boolean;
      vaultRead?: VerifiedVaultRead;
    },
  ): Promise<RetrievedDocument[]> {
    const withVectors = Boolean(args.needEmbeddings) && !args.keyless;
    const tsquery = args.keyless ? anyTermsQuery(args.query) : args.query;
    if (!tsquery.trim()) return [];
    const params: unknown[] = [tsquery, args.limit, args.organizationUuid];
    const filter = buildDocFilterClause(args.filters, params, VAULT_FILTER_COLUMNS, args.vaultRead?.verifiedScope.programIds);
    // tenant-isolation-safe: explicit organization predicate ($3), as the dense arm.
    const { rows } = await client.query(
      `
      SELECT
        c.id AS chunk_id,
        c.document_id AS document_id,
        d.program_id::text AS program_id, d.content_hash,
        COALESCE(d.document_title, d.file_name, '') ||
          CASE WHEN ${vaultBinaryAvailableSql('d')} THEN ''
          ELSE ' [original file unavailable; retained extracted data]' END AS title,
        c.chunk_text AS content,
        c.page_number AS page_number,
        c.section_title AS section_title,
        c.chunk_index AS chunk_index,
        c.char_start, c.char_end,
        encode(sha256(convert_to(d.extracted_text, 'UTF8')), 'hex') AS extracted_text_sha256,
        ${withVectors ? 'c.embedding::text AS embedding,' : ''}
        ${args.keyless
          ? "ts_rank_cd(to_tsvector('english', c.chunk_text), websearch_to_tsquery('english', $1), 32)::float8"
          : '0::float8'} AS similarity
      FROM vault.document_chunks c
      JOIN vault.documents d ON d.id = c.document_id
      WHERE ${withVectors ? 'c.embedding IS NOT NULL' : 'TRUE'}${filter}
        AND d.deleted_at IS NULL
        AND ${vaultDataEligibleSql('d')}
        AND NOT ${supersededSql('d')}
        AND EXISTS (SELECT 1 FROM regulatory_programs p WHERE p.id = d.program_id AND p.organization_id = d.organization_id AND p.deleted_at IS NULL)
        AND to_tsvector('english', c.chunk_text) @@ websearch_to_tsquery('english', $1)
        AND d.organization_id IN (SELECT o.id FROM organizations o WHERE o.uuid = $3::uuid)
      ORDER BY ts_rank_cd(to_tsvector('english', c.chunk_text), websearch_to_tsquery('english', $1)) DESC
      LIMIT $2
    `,
      params
    );
    const adapted = rows.map(readVaultChunkRow);
    return adapted.map(row => ({ ...vaultChunkToDoc(row, withVectors), ...(args.keyless ? { lexicalOnly: true } : {}) }));
  }

  private async searchVaultSimilar(
    query: string,
    limit: number,
    threshold: number,
    organizationUuid?: string,
    needEmbeddings?: boolean,
    hybrid?: boolean,
    filters?: QueryFilters,
    vaultRead?: VerifiedVaultRead,
    sourceReadScope?: AdmittedAnaSourceReadScope,
  ): Promise<RetrievedDocument[]> {
    // Metadata pre-filters on the joined documents table. Each arm has its own
    // param array, so each gets its own clause with arm-local placeholders.
    /* REFUSE WITHOUT A TENANT, rather than searching every tenant's vault.
       `organizationUuid` is optional on this path and `withTenantContext` simply
       does not set `app.current_org_id` when it is absent — so the two comments
       below that called these queries "RLS-scoped" were describing a boundary
       that, with no org, was never established. Both queries also carried no org
       predicate of their own, delegating entirely to RLS on vault.documents and
       vault.document_chunks, which are ENABLE ROW LEVEL SECURITY without FORCE
       (db/migrations/044c_gcc_vault_schema.sql:112,
       migrations/20260905b_vault_document_chunks.sql:76). Postgres does not
       apply ENABLE-only policies to the table OWNER, and
       server/db/getDatabaseUrl.ts:77-83 falls back to the owner URL when
       APP_DATABASE_URL is unset — the default single-role deployment. So on that
       shape there was no tenant boundary on vault retrieval at all.
       Returning nothing is the honest answer to "search this tenant's vault"
       asked with no tenant. */
    if (!organizationUuid || !UUID_RE.test(organizationUuid)) {
      if (sourceReadScope) throw new Error('The source organization identity could not be verified. Nothing was searched.');
      /* A malformed value is refused rather than passed to `$N::uuid`, which
         raises 22P02 and would surface as a retrieval failure rather than as
         the authorization refusal it actually is. */
      console.warn(
        '[RAG] vault retrieval skipped: no usable organizationUuid on the request. ' +
          'Refusing rather than searching across tenants.'
      );
      return [];
    }

    /* KEYLESS BY DEFAULT. With no embedding provider (no key, or a tenant whose
       placement policy refuses egress) the query cannot be embedded, and this
       arm used to throw, so AnA could not search the Vault at all. The text
       index on chunk_text answers instead (vaultLexicalArm), and every passage
       found that way says so (`lexicalOnly`), so a caller can state how the
       search was ranked. An embedding, when there is one, only adds the
       meaning-based arm. Embedded after the tenant refusal above, so a refused
       call sends nothing to a provider. */
    const vector = await this.queryVectorOrNull(query, this.embeddingsForVaultRead(vaultRead));
    if (vector === null) {
      return this.withVaultReadExecutor(organizationUuid, vaultRead, sourceReadScope, client =>
        this.vaultLexicalArm(client, { query, limit, organizationUuid, filters, keyless: true, vaultRead }));
    }

    const denseParams: unknown[] = [vector, threshold, limit, organizationUuid];
    const denseFilter = buildDocFilterClause(filters, denseParams, VAULT_FILTER_COLUMNS, vaultRead?.verifiedScope.programIds);

    // Ship the stored vector (as text) only when MMR will reuse it. SELECT-list
    // columns take no params, so this doesn't shift the $1..$3 placeholders.
    const embeddingCol = needEmbeddings ? 'c.embedding::text AS embedding,' : '';

    const toDoc = (row: VaultChunkRow) => vaultChunkToDoc(row, needEmbeddings);

    return this.withVaultReadExecutor(organizationUuid, vaultRead, sourceReadScope, async client => {
      /* ── Scope to the tenant FIRST, then rank exactly ──────────────────────
         This arm used to be one query: `ORDER BY c.embedding <=> $1 LIMIT $3`
         with the tenant and distance predicates in the same WHERE. Once the
         planner chose the approximate index on vault.document_chunks
         (ivfflat, probes = 1 by default), the scan took its candidates from
         ONE list and the WHERE then filtered them — so when that list held
         another tenant's chunks, or none above the threshold, the arm
         returned nothing while this tenant's matching passages sat in lists
         it never probed. search_document_passages then said "No passage
         matched" beside a coverage line saying every document was indexed: a
         miss presented as an exhaustive search. It depends on table
         statistics, which is why it passed on near-empty test databases and
         is exactly the shape production reaches with every tenant's chunks in
         one table (tests/db/vault-passage-search.dbtest.ts forces that plan).

         The MATERIALIZED CTE fixes the order of operations: the tenant's
         chunks are selected through the btree indexes, and only then ordered
         by distance — exactly, over rows that are all this tenant's. The
         approximate index cannot short-circuit a sort over a materialized
         CTE. For a regulatory answer, recall is not a tunable; the cost is a
         distance computation per chunk the tenant holds. */
      // tenant-isolation-safe: the WHERE carries an explicit organization
      // predicate ($4 -> organizations.uuid -> organizations.id ->
      // vault.documents.organization_id). RLS is defence in depth here, not the
      // boundary — see the refusal above for why it could not be relied on.
      let denseRows: VaultChunkRow[];
      const savepoint = await optionalVaultSavepoint(client);
      try {
        const { rows } = await client.query(
          vaultDensePassageSql(denseFilter, embeddingCol), denseParams,
        );
        denseRows = rows.map(readVaultChunkRow);
        if (savepoint) await client.query('RELEASE SAVEPOINT vault_dense_search');
      } catch (error) {
        await recoverVaultSavepoint(client, savepoint);
        // 42703 / 42883: no embedding column or no vector operator on this
        // database (no pgvector). The index, not the corpus, is absent.
        if (!missingVectorIndex(error)) throw error;
        return this.vaultLexicalArm(client, { query, limit, organizationUuid, filters, keyless: true, vaultRead });
      }
      const dense = denseRows.map(toDoc);
      if (!hybrid) return dense;

      // Sparse arm: Postgres full-text over chunk_text (vaultLexicalArm). A
      // lexical failure must not break retrieval: fall back to the dense arm.
      let lexical: RetrievedDocument[];
      try {
        lexical = await this.vaultLexicalArm(client, {
          query, limit, organizationUuid, filters, keyless: false, needEmbeddings, vaultRead,
        });
      } catch (error) {
        if (vaultRead || sourceReadScope) throw error;
        console.warn('[RAG] vault lexical arm failed; using dense-only retrieval:', error);
        return dense;
      }

      return fuseHybrid(dense, lexical, limit);
    });
  }

  /**
   * Initial retrieval against the rag_chunks corpus (the registered hot-path
   * chunk store, also used by the biotech surface). Mirrors searchVaultSimilar
   * but reads rag_chunks / rag_documents and scopes by the integer
   * organization_id. rag_chunks is not RLS-scoped, so the org filter is applied
   * explicitly — when organizationId is omitted, all tenants' chunks are
   * eligible, so callers serving a single tenant must pass it.
   *
   * Same embedding space as the vault path (text-embedding-3-small, 1536d) per
   * embedding-corpus-policy, so query embedding and similarity are identical.
   */
  private async searchRagChunksSimilar(
    query: string,
    limit: number,
    threshold: number,
    organizationId?: number,
    needEmbeddings?: boolean,
    hybrid?: boolean,
    filters?: QueryFilters
  ): Promise<RetrievedDocument[]> {
    const queryResult = await this.embeddingService.embed(query, 'text-embedding-3-small');
    const vector = `[${queryResult.embedding.join(',')}]`;

    const params: Array<string | number | Date> = [vector, threshold, limit];
    let orgFilter = '';
    if (organizationId !== undefined && organizationId !== null) {
      params.push(organizationId);
      orgFilter = `AND d.organization_id = $${params.length}`;
    }
    // Metadata pre-filters follow the org filter so placeholders stay sequential.
    const denseFilter = buildDocFilterClause(filters, params, RAG_FILTER_COLUMNS);

    // Ship the stored vector (as text) only when MMR will reuse it.
    const embeddingCol = needEmbeddings ? 'c.embedding::text AS embedding,' : '';

    const toDoc = (row: VaultChunkRow): RetrievedDocument => ({
      id: row.chunk_id,
      chunkId: row.chunk_id,
      documentId: row.document_id,
      content: row.content || '',
      title: row.title || 'Untitled',
      atomType: 'rag_chunk',
      initialScore: Number(row.similarity),
      finalScore: Number(row.similarity),
      pageNumber: row.page_number ?? undefined,
      sectionTitle: row.section_title,
      chunkIndex: row.chunk_index ?? undefined,
      locator: buildLocator(row),
      embedding: needEmbeddings ? parsePgVector(row.embedding) : undefined,
    });

    // tenant-isolation-safe: org filter is interpolated via ${orgFilter} (AND d.organization_id = $N) when organizationId is supplied — the static scanner can't see interpolated predicates; single-tenant callers must pass organizationId (see method doc).
    const { rows: denseRows } = await this.pool.query<VaultChunkRow>(
      `
        SELECT
          c.id AS chunk_id,
          c.document_id AS document_id,
          COALESCE(d.title, '') || CASE WHEN ${ragOriginalFileAvailableSql('d')} THEN ''
            ELSE ' [original file unavailable; retained extracted data]' END AS title,
          c.content AS content,
          c.page_number AS page_number,
          c.section_title AS section_title,
          c.chunk_index AS chunk_index,
          ${embeddingCol}
          1 - (c.embedding <=> $1::vector) AS similarity
        FROM rag_chunks c
        JOIN rag_documents d ON d.id = c.document_id
        WHERE c.embedding IS NOT NULL
          AND ${ragDataEligibleSql('d')}
          ${orgFilter}${denseFilter}
          -- (1 - sim) filter as a distance bound: 1 - dist > t  <=>  dist < 1 - t.
          -- Uses the same bare <=> operator as ORDER BY so the planner reuses
          -- the distance and the predicate matches the indexed cosine operator.
          -- $2 is cast explicitly: in "1 - $2" Postgres infers the parameter
          -- from the integer literal, and a float threshold like 0.65 then
          -- fails with 22P02 before the query ever runs.
          AND (c.embedding <=> $1::vector) < 1 - $2::float8
        ORDER BY c.embedding <=> $1::vector
        LIMIT $3
      `,
      params
    );
    const dense = denseRows.map(toDoc);
    if (!hybrid) return dense;

    // Sparse arm: same RRF hybrid as the vault path. The org filter reuses the
    // $N placeholder already bound above; the lexical query takes the raw query
    // text as $1 and limit as $2, so its own org placeholder (if any) is $3.
    const lexParams: Array<string | number | Date> = [query, limit];
    let lexOrgFilter = '';
    if (organizationId !== undefined && organizationId !== null) {
      lexParams.push(organizationId);
      lexOrgFilter = `AND d.organization_id = $${lexParams.length}`;
    }
    const lexFilter = buildDocFilterClause(filters, lexParams, RAG_FILTER_COLUMNS);
    let lexical: RetrievedDocument[];
    try {
      // tenant-isolation-safe: org filter is interpolated via ${lexOrgFilter} (AND d.organization_id = $N) when organizationId is supplied — mirrors the dense arm; the static scanner can't see interpolated predicates.
      const { rows: lexRows } = await this.pool.query<VaultChunkRow>(
        `
        SELECT
          c.id AS chunk_id,
          c.document_id AS document_id,
          COALESCE(d.title, '') || CASE WHEN ${ragOriginalFileAvailableSql('d')} THEN ''
            ELSE ' [original file unavailable; retained extracted data]' END AS title,
          c.content AS content,
          c.page_number AS page_number,
          c.section_title AS section_title,
          c.chunk_index AS chunk_index,
          ${embeddingCol}
          0::float8 AS similarity
        FROM rag_chunks c
        JOIN rag_documents d ON d.id = c.document_id
        WHERE c.embedding IS NOT NULL
          AND ${ragDataEligibleSql('d')}
          ${lexOrgFilter}${lexFilter}
          AND to_tsvector('english', c.content) @@ websearch_to_tsquery('english', $1)
        ORDER BY ts_rank_cd(to_tsvector('english', c.content), websearch_to_tsquery('english', $1)) DESC
        LIMIT $2
      `,
        lexParams
      );
      lexical = lexRows.map(toDoc);
    } catch (error) {
      console.warn('[RAG] rag_chunks lexical arm failed; using dense-only retrieval:', error);
      return dense;
    }

    return fuseHybrid(dense, lexical, limit);
  }

  /**
   * Wrap a memory row (SELECT *, similarity) as a RetrievedDocument, carrying the
   * full row in sourceRow so the memory shims reconstruct their rich entry type.
   */
  private memoryRowToDocument(
    row: Record<string, any>,
    atomType: 'client_memory' | 'project_memory',
    needEmbeddings?: boolean
  ): RetrievedDocument {
    const similarity = Number(row.similarity);
    return {
      id: String(row.id),
      documentId: String(row.id),
      content: typeof row.content === 'string' ? row.content : String(row.content ?? ''),
      title: typeof row.title === 'string' ? row.title : String(row.title ?? ''),
      atomType,
      initialScore: similarity,
      finalScore: similarity,
      sourceRow: row,
      // `SELECT *` already returns the vector; only spend the parse when MMR
      // will use it (memory corpora normally run MMR-off, so this stays unset).
      embedding: needEmbeddings ? parsePgVector(row.embedding) : undefined,
    };
  }

  /**
   * Initial retrieval against the client_memory_entries corpus. Byte-for-byte the
   * same query (and param order) as the legacy searchMemoryEntriesSemantic, now
   * reached through the single router. Invoke with strategy 'basic' and
   * reranking/MMR/compression off so ranking stays pure similarity.
   */
  private async searchClientMemorySimilar(
    query: string,
    limit: number,
    threshold: number,
    scope: CorpusScope
  ): Promise<RetrievedDocument[]> {
    const organizationId = scope.organizationId;
    if (organizationId === undefined || organizationId === null) return [];
    const profileId = scope.memory?.profileId ?? null;
    const category = scope.memory?.category;

    const queryResult = await this.embeddingService.embed(query, 'text-embedding-3-small');
    const vector = `[${queryResult.embedding.join(',')}]`;

    const params: Array<string | number> = profileId
      ? [vector, organizationId, profileId, threshold]
      : [vector, organizationId, threshold];
    const profileClause = profileId ? 'AND profile_id = $3' : '';
    const thresholdIdx = profileId ? 4 : 3;
    let categoryClause = '';
    if (category) {
      params.push(category);
      categoryClause = `AND category = $${params.length}`;
    }
    params.push(limit);

    const { rows } = await this.pool.query(
      `SELECT
         *,
         1 - (embedding <=> $1::vector) AS similarity
       FROM client_memory_entries
       WHERE organization_id = $2
         ${profileClause}
         AND status = 'active'
         AND embedding IS NOT NULL
         AND 1 - (embedding <=> $1::vector) >= $${thresholdIdx}
         ${categoryClause}
       ORDER BY embedding <=> $1::vector
       LIMIT $${params.length}`,
      params
    );

    return rows.map(row => this.memoryRowToDocument(row, 'client_memory', scope.needEmbeddings));
  }

  /**
   * Initial retrieval against the project_memory_entries corpus. Mirror of the
   * legacy searchProjectMemoryEntriesSemantic query and param order.
   */
  private async searchProjectMemorySimilar(
    query: string,
    limit: number,
    threshold: number,
    scope: CorpusScope
  ): Promise<RetrievedDocument[]> {
    const organizationId = scope.organizationId;
    const projectId = scope.memory?.projectId;
    if (organizationId === undefined || organizationId === null) return [];
    if (projectId === undefined || projectId === null) return [];
    const projectProfileId = scope.memory?.projectProfileId ?? null;
    const category = scope.memory?.category;

    const queryResult = await this.embeddingService.embed(query, 'text-embedding-3-small');
    const vector = `[${queryResult.embedding.join(',')}]`;

    const params: Array<string | number> = projectProfileId
      ? [vector, organizationId, projectId, projectProfileId, threshold]
      : [vector, organizationId, projectId, threshold];
    const profileClause = projectProfileId ? 'AND project_profile_id = $4' : '';
    const thresholdIdx = projectProfileId ? 5 : 4;
    let categoryClause = '';
    if (category) {
      params.push(category);
      categoryClause = `AND category = $${params.length}`;
    }
    params.push(limit);

    const { rows } = await this.pool.query(
      `SELECT
         *,
         1 - (embedding <=> $1::vector) AS similarity
       FROM project_memory_entries
       WHERE organization_id = $2
         AND project_id = $3
         ${profileClause}
         AND status = 'active'
         AND source_document_type IS DISTINCT FROM 'report_os_state'
         AND embedding IS NOT NULL
         AND 1 - (embedding <=> $1::vector) >= $${thresholdIdx}
         ${categoryClause}
       ORDER BY embedding <=> $1::vector
       LIMIT $${params.length}`,
      params
    );

    return rows.map(row => this.memoryRowToDocument(row, 'project_memory', scope.needEmbeddings));
  }

  private async persistEvidenceCitations(
    client: pg.PoolClient,
    organizationUuid: string,
    query: string,
    citations: Array<{
      documentId?: string;
      chunkId?: string;
      quote: string;
      locator?: string;
      confidence: number;
    }>
  ): Promise<void> {
    const filtered = citations.filter(c => c.documentId && c.chunkId);
    if (!filtered.length) {
      return;
    }

    const quantize = (value: number) => Math.round(value * 1e6) / 1e6;

    for (const citation of filtered) {
      const citationId = randomUUID();
      await client.query(
        `
        INSERT INTO vault.evidence_citations (
          id,
          source_document_id,
          source_chunk_id,
          claim_text,
          evidence_document_id,
          evidence_chunk_id,
          evidence_text,
          relevance_score,
          support_type,
          citation_context,
          created_at
        ) SELECT
          $1,
          $2,
          $3,
          $4,
          $2,
          $3,
          $5,
          $6,
          'SUPPORTS',
          $7,
          now()
          FROM vault.document_chunks c JOIN vault.documents d ON d.id=c.document_id
         WHERE c.id=$3 AND d.id=$2 AND d.deleted_at IS NULL
           AND d.organization_id IN (SELECT o.id FROM organizations o WHERE o.uuid=$8::uuid)
           AND ${vaultDataEligibleSql('d')}
      `,
        [
          citationId,
          citation.documentId,
          citation.chunkId,
          query,
          citation.quote,
          quantize(citation.confidence),
          citation.locator ?? null,
          organizationUuid,
        ]
      );
    }
  }

  /**
   * Merge and deduplicate documents from multiple sources
   */
  /**
   * Lexical fallback similarity (Jaccard on words). Only used when embedding
   * the candidates for MMR fails; the primary path is cosine in embedding space.
   */
  private calculateTextSimilarity(text1: string, text2: string): number {
    const words1 = new Set(text1.toLowerCase().split(/\s+/));
    const words2 = new Set(text2.toLowerCase().split(/\s+/));

    const intersection = new Set([...words1].filter(x => words2.has(x)));
    const union = new Set([...words1, ...words2]);

    return union.size === 0 ? 0 : intersection.size / union.size;
  }

  /**
   * Scale a vector to unit length once, up front. Cosine similarity between two
   * unit vectors is then just their dot product, so MMR's inner loop avoids
   * recomputing norms on every pairwise comparison. A zero vector maps to zero
   * (yields 0 similarity), matching the old guard.
   */
  private normalize(v: number[]): number[] {
    let norm = 0;
    for (let i = 0; i < v.length; i++) norm += v[i] * v[i];
    norm = Math.sqrt(norm);
    if (norm === 0) return new Array<number>(v.length).fill(0);
    const out = new Array<number>(v.length);
    for (let i = 0; i < v.length; i++) out[i] = v[i] / norm;
    return out;
  }

  /**
   * Dot product of two vectors. On unit-normalized inputs this equals cosine
   * similarity; on zero vectors it returns 0.
   */
  private dotProduct(a: number[], b: number[]): number {
    const len = Math.min(a.length, b.length);
    let dot = 0;
    for (let i = 0; i < len; i++) dot += a[i] * b[i];
    return dot;
  }

  /**
   * Route an auxiliary LLM call through an in-memory TTL cache keyed by the
   * request shape. Identical HyDE / expansion / rerank / compression calls
   * within the TTL reuse the prior result instead of paying for another
   * round-trip. The final answer generation does NOT use this.
   */
  private async routeCached(request: AIRequest): Promise<AIResponse> {
    // A cache hit is model output served without a call: refused where a
    // model may not be called, before the lookup (row 74, S5c).
    await refuseModelCallHere('RAG response cache');
    // The tenant and its placement policy are part of the key. The pipeline is
    // a process singleton, and until 2026-09-26 the key was the request shape
    // alone: a hit served one tenant another tenant's model output, produced
    // under that tenant's placement, with no placement check and no ledger row
    // for the tenant that got it — and outlived a policy change by the full TTL
    // (docs/evidence/D6/2026-09-26-refusals-are-final/). A policy that cannot be
    // read bypasses the cache, so the gateway decides.
    const tenant = getTenantScope()?.tenantId ?? null;
    let placement: string;
    try {
      placement = JSON.stringify((await getOrgPlacementResolver().resolve(tenant ?? undefined)) ?? null);
    } catch {
      return this.aiRouter.route(request);
    }
    const key = createHash('sha256')
      .update(
        JSON.stringify({
          tenant,
          placement,
          taskType: request.taskType,
          messages: request.messages,
          maxTokens: request.maxTokens,
          temperature: request.temperature,
          jsonMode: request.jsonMode,
        })
      )
      .digest('hex');

    const now = Date.now();
    const hit = this.llmCallCache.get(key);
    if (hit) {
      if (hit.expiresAt > now) {
        // Live hit: re-insert so it becomes the most-recently-used entry. A
        // Map preserves insertion order, so this makes eviction true LRU (the
        // key returned by keys().next() is the least-recently-used).
        this.llmCallCache.delete(key);
        this.llmCallCache.set(key, hit);
        return { ...hit.value, cached: true };
      }
      // Expired: drop it so it doesn't linger as a stale eviction candidate.
      this.llmCallCache.delete(key);
    }

    const value = await this.aiRouter.route(request);
    this.llmCallCache.set(key, { value, expiresAt: now + this.llmCacheTtlMs });

    // Bound the cache: drop the least-recently-used entry once over capacity.
    if (this.llmCallCache.size > this.llmCacheMaxEntries) {
      const lru = this.llmCallCache.keys().next().value as string | undefined;
      if (lru) this.llmCallCache.delete(lru);
    }

    return value;
  }

  /** Assemble the `[Source N: title]` block fed to generation and the self-checks. */
  private buildSourceText(documents: RetrievedDocument[]): string {
    return buildRagSourceText(documents);
  }

  private async correctContext(
    query: string, context: RAGContext, options: RetrievalOptions,
  ): Promise<RAGContext> {
    if (!options.useCorrectiveLoop) return context;
    const route = (req: AIRequest) => this.routeCached(req);
    const grade = await gradeContextSufficiency(route, query, this.buildSourceText(context.documents));
    context.tokensUsed += grade.tokensUsed;
    if (grade.sufficient) return context;
    const rewrite = await rewriteQuery(route, query);
    context.tokensUsed += rewrite.tokensUsed;
    if (rewrite.query === query) return context;
    const retried = await this.retrieve(rewrite.query, options);
    if (!retried.documents.length) return context;
    retried.tokensUsed += context.tokensUsed;
    return retried;
  }

  async queryWithGeneration(
    query: string,
    options: RetrievalOptions = { strategy: 'advanced', useReranking: true, useMmr: true }
  ): Promise<{
    answer: string;
    sources: RetrievedDocument[];
    context: RAGContext;
    /** Faithfulness verdict; only present when useCorrectiveLoop is set. */
    grounded?: boolean;
  }> {
    if (options.vaultRead) {
      throw new ProgramReadAccessError(403, 'VAULT_SCOPED_GENERATION_UNSUPPORTED',
        'The verified Vault read scope is available for retrieval only.');
    }
    // Retrieve relevant documents
    let context = await this.retrieve(query, options);
    const refuse = () => {
      context = { ...context, documents: [] };
      return { answer: RAG_EMPTY_CONTEXT_REFUSAL, sources: [], context };
    };
    context.documents = await this.revalidateCandidates(context.documents, options);

    if (context.documents.length === 0) {
      return refuse();
    }

    const route = (req: AIRequest) => this.routeCached(req);

    // Corrective pre-generation (CRAG): grade whether the retrieved sources can
    // answer the question; if not, rewrite the query and retrieve once more,
    // keeping the new context when it returns results. Bounded to a single retry.
    context = await this.correctContext(query, context, options);

    context.documents = await this.revalidateCandidates(context.documents, options);
    if (!context.documents.length) return refuse();
    // Build context for generation
    const sourceText = this.buildSourceText(context.documents);

    // Generate answer. `options.model`, when set, pins WHICH model answers so
    // the run can be attributed to it (a PQ requirement); unset keeps the
    // gateway's task-type selection, which is every existing caller.
    const response = await this.aiRouter.route({
      ...buildRagGenerationRequest(query, sourceText),
      ...(options.model ? { model: options.model } : {}),
    });

    // A withdrawal during generation invalidates the answer's entire grounding;
    // dropping only its citation would still return claims derived from it.
    const stillCurrent = async () => {
      const previous = context.documents;
      const current = await this.revalidateCandidates(previous, options);
      const unchanged = current.length === previous.length && current.every((d, i) =>
        d.id === previous[i].id && d.atomType === previous[i].atomType &&
        d.originalFileAvailable === previous[i].originalFileAvailable);
      context.documents = current;
      return unchanged;
    };
    if (!await stillCurrent()) return refuse();

    if (options.persistCitations && options.organizationUuid) {
      const citations = context.documents.map(doc => ({
        documentId: doc.documentId,
        chunkId: doc.chunkId,
        quote: doc.compressedContent || doc.expandedContent || doc.content,
        locator: doc.locator,
        confidence: doc.finalScore,
      }));

      try {
        await withTenantContext(this.pool, options.organizationUuid, async client => {
          await this.persistEvidenceCitations(client, options.organizationUuid!, query, citations);
        });
      } catch (error) {
        console.warn('[RAG] Citation persistence failed:', error);
      }
    }

    // Corrective post-generation: groundedness / faithfulness guard. Opt-in, and
    // it annotates the result (a `grounded` flag the caller can act on) rather
    // than withholding the answer.
    let grounded: boolean | undefined;
    if (options.useCorrectiveLoop) {
      if (!await stillCurrent()) return refuse();
      const check = await verifyGroundedness(route, response.content, sourceText);
      context.tokensUsed += check.tokensUsed;
      grounded = check.grounded;
    }
    if (!await stillCurrent()) return refuse();

    return {
      answer: response.content,
      sources: context.documents,
      context,
      ...(grounded === undefined ? {} : { grounded }),
    };
  }
}

