let ragPipeline: AdvancedRAGPipeline | null = null;

export function getRAGPipeline(pool: pg.Pool): AdvancedRAGPipeline {
  if (!ragPipeline) {
    ragPipeline = new AdvancedRAGPipeline(pool);
  }
  return ragPipeline;
}
